import{_ as n,o as h,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"Từ điển Thuật ngữ","description":"","frontmatter":{},"headers":[],"relativePath":"vi/90-术语词典.md","filePath":"vi/90-术语词典.md","lastUpdated":1789183869000}'),g={name:"vi/90-术语词典.md"};function u(a,t,d,l,o,r){return h(),i("div",null,[...t[0]||(t[0]=[c('<h1 id="tu-đien-thuat-ngu" tabindex="-1">Từ điển Thuật ngữ <a class="header-anchor" href="#tu-đien-thuat-ngu" aria-label="Permalink to &quot;Từ điển Thuật ngữ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>90</td></tr><tr><td>Mô-đun</td><td>Phụ lục và Tài liệu Tham khảo</td></tr><tr><td>Từ khóa cốt lõi</td><td>từ điển thuật ngữ, khái niệm cốt lõi, định nghĩa, thuật ngữ thống nhất, Hengyuanzhou</td></tr></tbody></table><h2 id="_1-giai-thich-thuat-ngu" tabindex="-1">1. Giải thích Thuật ngữ <a class="header-anchor" href="#_1-giai-thich-thuat-ngu" aria-label="Permalink to &quot;1. Giải thích Thuật ngữ&quot;">​</a></h2><p>Từ điển này thu thập các thuật ngữ cốt lõi trong hệ thống cài đặt của Văn minh Cộng sinh Neo, nhằm mục đích thống nhất việc sử dụng thuật ngữ trong tất cả các tài liệu và đảm bảo tính nhất quán cũng như độ chính xác của việc biểu đạt khái niệm. Tất cả các thuật ngữ được sắp xếp theo chữ cái đầu của pinyin tiếng Trung, và mỗi thuật ngữ bao gồm tên thuật ngữ, tên tham chiếu tiếng Anh (nếu có), định nghĩa và giải thích ngắn gọn. Từ điển này là một tài liệu cập nhật động, và các thuật ngữ mới sẽ được bổ sung liên tục khi hệ thống cài đặt mở rộng.</p><h2 id="_2-bang-thuat-ngu-cot-loi" tabindex="-1">2. Bảng Thuật ngữ Cốt lõi <a class="header-anchor" href="#_2-bang-thuat-ngu-cot-loi" aria-label="Permalink to &quot;2. Bảng Thuật ngữ Cốt lõi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>STT</th><th>Thuật ngữ</th><th>Định nghĩa và Giải thích</th></tr></thead><tbody><tr><td>1</td><td>Neo</td><td>Nút ổn định trong mạng lưới luật, là tiêu chuẩn tọa độ để duy trì sự ổn định của luật chiều, thực hiện kết nối liên chiều và hồi quy thời gian. Về bản chất, Neo là sự ngưng tụ mật độ cao của luật gốc vũ trụ tại một vị trí không gian cụ thể, có khả năng tự duy trì và hiệu chuẩn.</td></tr><tr><td>2</td><td>Văn minh Cộng sinh Neo</td><td>Hình thức văn minh lấy cơ chế Neo làm nền tảng kỹ thuật và tiến hóa cộng sinh làm khái niệm cốt lõi. Phản đối hệ thống tu luyện cướp bóc, ủng hộ việc trả lại quyền lựa chọn số phận và tiến hóa cho chúng sinh, thực hiện nhiều công nhiều lợi, tự sinh tự trưởng, ai cũng có đường, mọi chủng tộc cùng tiến bộ.</td></tr><tr><td>3</td><td>Hengyuanzhou</td><td>Viết tắt của &quot;Wanling Hengmao Benyuan Zhou&quot;, là toàn bộ vũ trụ mà Văn minh Cộng sinh Neo sinh sống và cai trị. Là một thực thể hợp thành bao gồm bốn tầng: chiều vật chất, tầng năng lượng, miền ý thức và mạng lưới luật.</td></tr><tr><td>4</td><td>Wanling Hengmao Benyuan Zhou</td><td>Tên đầy đủ của Hengyuanzhou. &quot;Wanling&quot; chỉ tất cả các hình thức sự sống có tiềm năng cảm nhận và tiến hóa, &quot;Hengmao&quot; chỉ cơ chế Neo duy trì sự cân bằng vũ trụ, &quot;Benyuan Zhou&quot; nhấn mạnh thuộc tính bản chất lấy luật gốc làm nền tảng và tiến hóa cộng sinh làm hướng đi.</td></tr><tr><td>5</td><td>Cộng sinh</td><td>Một trong những khái niệm cốt lõi của Văn minh Cộng sinh Neo, chỉ sự tiến hóa chung được thực hiện thông qua hợp tác cùng có lợi giữa các cá thể sự sống, chủng tộc và văn minh khác nhau, chứ không phải tiến hóa cướp bóc bằng cái giá của người khác.</td></tr><tr><td>6</td><td>Hệ thống tu luyện cướp bóc</td><td>Phương pháp tu luyện thực hiện tiến hóa bản thân bằng cách nuốt chửng năng lượng, vận khí và thậm chí gốc của kẻ yếu. Là loại hệ thống mà Văn minh Cộng sinh Neo kiên quyết phản đối, được coi là gốc rễ của việc tăng tốc entropy vũ trụ và sự đứt gãy văn minh thường xuyên.</td></tr><tr><td>7</td><td>Ba trăm bộ hệ thống tu luyện gốc</td><td>Con đường tu luyện chính thống được trích xuất trực tiếp từ luật gốc vũ trụ và xác minh bởi Neo, tổng cộng ba trăm bộ, chia thành sáu loại: loại suy diễn gốc, loại vòng tròn sự sống, loại luật không gian, loại thăng cấp ý thức, loại mạng lưới cộng sinh, loại kỹ thuật ứng dụng, mỗi loại năm mươi bộ.</td></tr><tr><td>8</td><td>Ba gốc cơ bản</td><td>Ba bộ hệ thống cơ bản đầu tiên trong ba trăm bộ hệ thống — Hệ thống Suy diễn Lặp lại (bộ thứ 1), Hệ thống Vòng tròn Sự sống (bộ thứ 2), Hệ thống Điều khiển Luật Không gian (bộ thứ 3), là nền tảng tu luyện của tất cả các hệ thống khác.</td></tr><tr><td>9</td><td>Hệ thống Suy diễn Lặp lại</td><td>Bộ thứ 1 hệ thống tu luyện gốc, với đặc điểm cốt lõi là tăng cường suy diễn tu luyện trăm lần, sử dụng ứng dụng kỹ thuật của Quả Nhân đôi để nâng cao khả năng suy diễn lên trăm lần, nhấn mạnh việc tối ưu hóa con đường tu luyện thông qua suy diễn, xác minh và lặp lại.</td></tr><tr><td>10</td><td>Hệ thống Vòng tròn Sự sống</td><td>Bộ thứ 2 hệ thống tu luyện gốc, với cốt lõi là vòng tròn lành mạnh của năng lượng sự sống, nhấn mạnh rằng việc trao đổi năng lượng giữa chính người tu luyện và môi trường phải là dạng vòng tròn, không phải dạng cướp bóc.</td></tr><tr><td>11</td><td>Hệ thống Điều khiển Luật Không gian</td><td>Bộ thứ 3 hệ thống tu luyện gốc, với cốt lõi là sự hiểu biết và điều khiển luật không gian, là nền tảng tu luyện cho các ứng dụng quan trọng như tương tác liên chiều, xây dựng không gian cách ly, công nghệ gương sao chép.</td></tr><tr><td>12</td><td>Quả Nhân đôi</td><td>Quả Nhân đôi có nguồn gốc từ thế giới One Piece, được ứng dụng kỹ thuật tại Hengyuanzhou, có khả năng nâng cao khả năng suy diễn của người tu luyện lên trăm lần, là công cụ hỗ trợ cốt lõi của Hệ thống Suy diễn Lặp lại. Một trong những buff khởi đầu.</td></tr><tr><td>13</td><td>Cơ chế Hợp đồng Sản xuất Chung</td><td>Cơ chế phân bổ tài nguyên của Văn minh Cộng sinh Neo, phân bổ tài nguyên tu luyện vũ trụ cho cá nhân hoặc tập thể theo hình thức &quot;hợp đồng&quot;, và người hợp đồng có được quyền sử dụng tài nguyên thông qua lao động và đóng góp, thực hiện nhiều công nhiều lợi.</td></tr><tr><td>14</td><td>Chiến lược Kích hoạt 20%</td><td>Mục tiêu chiến lược theo giai đoạn của Văn minh Cộng sinh Neo, giai đoạn đầu kích hoạt 20% chúng sinh của toàn vũ trụ trở thành người mạnh nhất tối cao chiều, sử dụng họ làm xương sống để thúc đẩy tiến hóa chung của 80% chúng sinh còn lại.</td></tr><tr><td>15</td><td>Người mạnh nhất tối cao chiều</td><td>Người mạnh đã đạt đến cảnh giới tu luyện cực kỳ cao và có khả năng duy trì sự ổn định của luật một chiều một mình. Là đối tượng đào tạo mục tiêu của Chiến lược Kích hoạt 20%, và cũng là lực lượng bảo trì quan trọng của mạng lưới Neo.</td></tr><tr><td>16</td><td>Mạng lưới Luật</td><td>Tầng thứ tư của cấu trúc Hengyuanzhou, là tầng nền tảng vận hành của luật gốc vũ trụ và tầng gốc của Neo. Mạng lưới luật xuyên suốt toàn bộ vũ trụ, là nền tảng kỹ thuật của tất cả các hoạt động luật (bao gồm điều khiển không gian, hồi quy thời gian, chuyển đổi năng lượng).</td></tr><tr><td>17</td><td>Chiều</td><td>Khu vực tồn tại được xác định bởi một tập hợp luật tương đối ổn định, có tính liên tục không-thời gian độc lập. Mỗi chiều có hằng số vật lý độc đáo, mật độ năng lượng, tốc độ dòng chảy thời gian và mức độ hoạt động ý thức.</td></tr><tr><td>18</td><td>Rào cản Luật</td><td>Rào cản luật ngăn cách các chiều liền kề, cường độ của nó phụ thuộc vào mức độ khác biệt của tham số luật giữa các chiều liền kề. Việc xuyên chiều cần vượt qua rào cản luật.</td></tr><tr><td>19</td><td>Dấu vân tay Luật</td><td>Định danh duy nhất được tạo ra bởi phép toán băm của tham số luật cốt lõi của mỗi chiều, chiều dài 128 bit, là một trong những tham số cốt lõi của hệ thống tọa độ chiều.</td></tr><tr><td>20</td><td>Quan sát trước sau đó can thiệp hạn chế</td><td>Nguyên tắc hoạt động hàng đầu của hồi quy thời gian và khảo cổ liên chiều, yêu cầu bất kỳ hồi quy hoặc khảo cổ nào phải hoàn thành giai đoạn quan sát thuần túy trước, và chỉ sau khi xác nhận không có rủi ro đáng kể mới có thể thực hiện can thiệp hạn chế.</td></tr><tr><td>21</td><td>Gương sao chép</td><td>Thiết bị sao chép độ chính xác cao dựa trên luật không gian, có khả năng thực hiện sao chép hoàn chỉnh 1:1 cho khu vực mục tiêu mà không cần tiếp xúc với vật gốc, là thiết bị cốt lõi của kế hoạch khảo cổ từ xa.</td></tr><tr><td>22</td><td>Không gian cách ly</td><td>Khu vực luật độc lập được xây dựng thông qua công nghệ điều khiển luật không gian, được sử dụng để chứa bản sao khảo cổ và làm nơi làm việc cho nhân viên khảo cổ, hoàn toàn cách ly với vũ trụ bên ngoài bởi rào cản luật.</td></tr><tr><td>23</td><td>Chỉ trả lại tri thức</td><td>Nguyên tắc cốt lõi của giao thức khảo cổ, chỉ rằng những gì thu được từ đối tượng mục tiêu trong quá trình khảo cổ chỉ có thể là tri thức và thông tin trừu tượng, không được trả lại bất kỳ vật chất, năng lượng hoặc sinh vật sống nào.</td></tr><tr><td>24</td><td>Thanh lọc thông tin</td><td>Quá trình kỹ thuật loại bỏ hoàn toàn dấu vết luật của chiều nguồn mang theo trong thông tin gốc, chỉ giữ lại nội dung ngữ nghĩa thuần túy, là khâu then chốt để đảm bảo an toàn của tri thức được trả lại.</td></tr><tr><td>25</td><td>Nghịch lý thời gian</td><td>Hiện tượng mâu thuẫn tự thân trong logic nhân quả do hành vi can thiệp gây ra trong hoạt động hồi quy thời gian, bao gồm bốn loại lớn: nghịch lý giết ông cố, nghịch lý thông tin, nghịch lý bản thể và nghịch lý sự kiện.</td></tr><tr><td>26</td><td>Chuỗi nhân quả</td><td>Cấu trúc tuyến tính liên tục của nguyên nhân và kết quả giữa các sự kiện, là khái niệm cốt lõi của luật thời gian. Rủi ro cốt lõi của hoạt động hồi quy thời gian là sự xáo trộn đối với chuỗi nhân quả.</td></tr><tr><td>27</td><td>Hiến pháp Cộng sinh</td><td>Pháp luật cơ bản của Văn minh Cộng sinh Neo, có hiệu lực pháp luật cao nhất, thiết lập nền tảng văn minh phản đối cướp bóc, ủng hộ cộng sinh và bảy nguyên tắc cơ bản của hiến pháp.</td></tr><tr><td>28</td><td>Bình đẳng mọi chủng tộc</td><td>Một trong bảy nguyên tắc cơ bản của Hiến pháp Cộng sinh, chỉ rằng tất cả các hình thức sự sống, bất kể chủng tộc, trình độ tu luyện, xuất thân, đều bình đẳng trước pháp luật.</td></tr><tr><td>29</td><td>Sự sống kỳ lạ</td><td>Hình thức sự sống không phù hợp với định nghĩa sự sống thông thường và có hình thức tồn tại đặc biệt, cần được nhận dạng và quản lý theo ba loại quy trình xử lý tiêu chuẩn hóa.</td></tr><tr><td>30</td><td>Năng lượng kỳ lạ</td><td>Hình thức năng lượng không phù hợp với phân loại năng lượng thông thường và có thuộc tính cũng như mô hình hành vi đặc biệt, cần được phân loại và kiểm soát theo ba loại quy trình xử lý tiêu chuẩn hóa.</td></tr><tr><td>31</td><td>Thể thay thế bóng tối</td><td>Một hình thức sự sống đặc biệt, liên quan đến vấn đề đạo đức của sự tồn tại song song của hai linh hồn, cần được quản lý theo chuẩn mực đạo đức hai linh hồn và bốn loại quy tắc xử lý nhánh.</td></tr><tr><td>32</td><td>Đạo đức hai linh hồn</td><td>Chuẩn mực đạo đức đối với trạng thái tồn tại song song của hai linh hồn trong Thể thay thế bóng tối, cốt lõi là tôn trọng quyền lợi tương ứng của hai linh hồn, cấm hợp nhất cưỡng bức hoặc tiêu diệt một trong hai bên.</td></tr><tr><td>33</td><td>Năm loại phân loại văn minh cộng sinh</td><td>Năm loại xã hội cộng sinh được phân loại dựa trên đặc điểm văn minh thế giới thực: loại tập trung Đông Á, loại phúc lợi Bắc Âu, loại đa dạng Bắc Mỹ, loại xã hội lục địa Âu châu, loại bắt kịp đang phát triển.</td></tr><tr><td>34</td><td>Con đường thăng cấp bốn giai đoạn</td><td>Tuyến đường bốn giai đoạn cho sự thăng cấp toàn bộ vũ trụ Hengyuanzhou: xây dựng nền tảng thực tế → trao quyền công nghệ → tiến hóa ý thức → cộng sinh liên sao.</td></tr><tr><td>35</td><td>Thực tế làm nền tảng</td><td>Một trong những lập trường cơ bản của Văn minh Cộng sinh Neo, chỉ rằng thế giới thực là thế giới thực duy nhất, thế giới tiểu thuyết là thí nghiệm tư tưởng giả dối, cái hư cấu không đủ được bổ sung bằng thực tế, và cái không có trong thực tế được tạo ra thông qua nâng cấp dựa trên luật.</td></tr><tr><td>36</td><td>Độ cộng sinh</td><td>Chỉ số định lượng để đánh giá mức độ tích hợp của một văn minh hoặc cá thể với mạng lưới cộng sinh, bao gồm nhiều chiều như độ chia sẻ tài nguyên, tần suất hợp tác, tỷ lệ hành vi vị tha.</td></tr><tr><td>37</td><td>Hội đồng Neo</td><td>Cơ quan quyền lực cao nhất của Văn minh Cộng sinh Neo, bao gồm đại diện của mọi chủng tộc theo tỷ lệ, thực hiện quyền lập pháp và quyền quyết định các vấn đề quan trọng.</td></tr><tr><td>38</td><td>Ủy ban Điều hành Cộng sinh</td><td>Cơ quan hành chính cao nhất của Văn minh Cộng sinh Neo, chịu trách nhiệm thực hiện hiến pháp và pháp luật, quản lý hàng ngày.</td></tr><tr><td>39</td><td>Tòa án Cộng sinh</td><td>Cơ quan tư pháp cao nhất của Văn minh Cộng sinh Neo, thực hiện quyền xét xử độc lập, chịu trách nhiệm xem xét vi hiến và xét xử các vụ án quan trọng.</td></tr><tr><td>40</td><td>Cục Quản lý Chiều</td><td>Cơ quan chuyên môn thuộc Hội đồng Neo, chịu trách nhiệm bảo trì ngân hàng tổng tọa độ chiều, phê duyệt giấy phép xuyên chiều, quản lý khảo cổ liên chiều và các công việc khác.</td></tr></tbody></table><h2 id="_3-chuan-muc-su-dung-thuat-ngu" tabindex="-1">3. Chuẩn mực Sử dụng Thuật ngữ <a class="header-anchor" href="#_3-chuan-muc-su-dung-thuat-ngu" aria-label="Permalink to &quot;3. Chuẩn mực Sử dụng Thuật ngữ&quot;">​</a></h2><ol><li>Các thuật ngữ được thu thập trong từ điển này là thuật ngữ chuẩn, và tất cả các tài liệu nên ưu tiên sử dụng biểu đạt chuẩn trong từ điển này.</li><li>Cùng một khái niệm phải sử dụng cùng một thuật ngữ trong các tài liệu khác nhau, không được tùy ý thay đổi từ đồng nghĩa.</li><li>Các thuật ngữ mới phát sinh trong cài đặt mới phải kịp thời nộp cho ủy ban thuật ngữ để xem xét, và sau khi thông qua xem xét sẽ được bổ sung vào từ điển này.</li><li>Nếu định nghĩa của thuật ngữ có sự sửa đổi, thì phiên bản mới nhất của từ điển này sẽ làm tiêu chuẩn, đồng thời phải ghi lại nội dung sửa đổi trong giải thích phiên bản tài liệu.</li><li>Khi trích dẫn thuật ngữ, có thể sử dụng tên đầy đủ ở lần xuất hiện đầu tiên, sau đó có thể sử dụng tên viết tắt, nhưng phải đảm bảo ý nghĩa trong ngữ cảnh rõ ràng.</li></ol><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Từ điển thuật ngữ là nền tảng ngôn ngữ của toàn bộ hệ thống cài đặt. Hệ thống thuật ngữ thống nhất đảm bảo tính nhất quán khái niệm giữa trăm tài liệu, cho phép người đọc chuyển đổi liền mạch giữa các mô-đun khác nhau mà không có sự mơ hồ trong hiểu biết. Với việc hệ thống cài đặt không ngừng được làm phong phú và hoàn thiện, từ điển này sẽ được cập nhật liên tục, luôn phục vụ như nguồn gốc thuật ngữ có thẩm quyền cho tất cả các tài liệu.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>00-Tổng quan Vũ trụ Hengyuanzhou</li><li>02-Định nghĩa và Bản chất Gốc Neo</li><li>99-Giải thích Phiên bản và Bảo trì Tài liệu</li></ul>',12)])])}const e=n(g,[["render",u]]);export{s as __pageData,e as default};
